let cache;
async function loadFiles(){
 if(!cache)cache=(async()=>{const bytes=Uint8Array.from(atob(compressed.replace(/\s+/g,'')),c=>c.charCodeAt(0));const content=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));return new Response(content).json();})();
 return cache;
}
export default {async fetch(request){
 try {
  const url=new URL(request.url);
  if(!['GET','HEAD'].includes(request.method))return new Response('Method Not Allowed',{status:405});
  let path=decodeURIComponent(url.pathname);
  if(path==='/')path='/index.html';
  if(path.includes('..')||path.includes('\\'))return new Response('Bad Request',{status:400});
  const asset=(await loadFiles())[path];
  if(!asset)return new Response('Not Found',{status:404});
  const payload=Uint8Array.from(atob(asset.b),c=>c.charCodeAt(0));
  const headers={'content-type':asset.t+((asset.t.startsWith('text/')||asset.t.includes('javascript'))?'; charset=utf-8':''),'cache-control':'no-store','x-content-type-options':'nosniff'};
  return new Response(request.method==='HEAD'?null:payload,{status:200,headers});
 } catch(e){return new Response('Internal server error',{status:500});}
}};
